import{_ as n,o,c as a,a0 as c}from"./chunks/framework.DhQjJcnt.js";const m=JSON.parse('{"title":"Skill: /common-spec","description":"","frontmatter":{},"headers":[],"relativePath":"references/skills/common-spec.md","filePath":"references/skills/common-spec.md"}'),i={name:"references/skills/common-spec.md"};function t(l,e,h,s,d,r){return o(),a("div",null,[...e[0]||(e[0]=[c('<h1 id="skill-common-spec" tabindex="-1">Skill: <code>/common-spec</code> <a class="header-anchor" href="#skill-common-spec" aria-label="Permalink to &quot;Skill: `/common-spec`&quot;">​</a></h1><h2 id="ten" tabindex="-1">Tên <a class="header-anchor" href="#ten" aria-label="Permalink to &quot;Tên&quot;">​</a></h2><p><code>common-spec</code></p><h2 id="cach-dung-command-trigger" tabindex="-1">Cách dùng (Command/Trigger) <a class="header-anchor" href="#cach-dung-command-trigger" aria-label="Permalink to &quot;Cách dùng (Command/Trigger)&quot;">​</a></h2><ul><li>Gọi qua slash command: <code>/common-spec</code></li><li>Tương tự như <code>/common</code>, Agent sẽ hỏi người dùng khai báo danh sách Consumer để tính toán vị trí cấp độ dùng chung (Lowest Common Ancestor - LCA).</li></ul><h2 id="input-du-lieu-đau-vao" tabindex="-1">Input (Dữ liệu đầu vào) <a class="header-anchor" href="#input-du-lieu-đau-vao" aria-label="Permalink to &quot;Input (Dữ liệu đầu vào)&quot;">​</a></h2><ul><li>Phạm vi dùng chung (Scope) do Member khai báo.</li><li>Các yêu cầu về mặt kỹ thuật, logic xử lý của các Component dùng chung (ví dụ: Confirm Dialog, Shared Layout, Middleware, Step Flow).</li></ul><h2 id="output-ket-qua-mong-đoi" tabindex="-1">Output (Kết quả mong đợi) <a class="header-anchor" href="#output-ket-qua-mong-đoi" aria-label="Permalink to &quot;Output (Kết quả mong đợi)&quot;">​</a></h2><ul><li>Sinh ra file cấu hình kỹ thuật dạng YAML Bundle: <code>common/yaml/&lt;slug&gt;/&lt;slug&gt;.bundle.yaml</code>. (Được sinh tại thư mục LCA).</li><li>Yêu cầu người dùng chạy lệnh <code>flowgrid split &lt;path&gt;</code> để chẻ file Bundle này ra thành <code>ir/design.yaml</code>, rồi dùng <code>flowgrid render</code> để sinh file đọc được.</li></ul><h2 id="description-y-nghia" tabindex="-1">Description / Ý nghĩa <a class="header-anchor" href="#description-y-nghia" aria-label="Permalink to &quot;Description / Ý nghĩa&quot;">​</a></h2><ul><li>Khác biệt hoàn toàn với <code>/common</code> (chỉ viết quy tắc bằng Markdown cho con người đọc), kỹ năng <code>/common-spec</code> sinh ra các <strong>cấu trúc kỹ thuật YAML</strong> để máy (hệ thống bộ code) đọc và sinh code.</li><li>Tính Đa nền tảng (Platform-Agnostic): Bundle sinh ra không bị gò bó vào Web, nó có thể tuỳ biến qua thẻ <code>design.shell.tag</code> thành Kiosk, Mobile App, hay Gateway Adapter tùy ý.</li><li>Nếu làm màn hình Web, Agent có thể đề xuất kế thừa từ 16 mẫu có sẵn trong <code>templates/project-skeleton/surfaces/common/yaml/</code>. Ngược lại, nếu làm hệ thống khác thì phải sinh file mới tinh.</li></ul><h2 id="cac-skill-lien-quan" tabindex="-1">Các Skill liên quan <a class="header-anchor" href="#cac-skill-lien-quan" aria-label="Permalink to &quot;Các Skill liên quan&quot;">​</a></h2><ul><li>Tuyệt đối không dùng <code>/common-spec</code> cho màn hình nghiệp vụ đơn lẻ, thay vào đó hãy dùng <code>/spec</code>.</li><li>Sinh xong bundle, bắt buộc bị kiểm định bởi <code>/grill-common-spec</code>.</li></ul><h2 id="chu-y-quan-trong" tabindex="-1">Chú ý quan trọng <a class="header-anchor" href="#chu-y-quan-trong" aria-label="Permalink to &quot;Chú ý quan trọng&quot;">​</a></h2><ul><li><strong>Tuyệt đối cấm:</strong> KHÔNG ĐƯỢC sinh ra file Markdown trực tiếp. Việc sinh file <code>.md</code> là nhiệm vụ của engine <code>/docs-hub</code> thông qua lệnh <code>split</code> và <code>render</code>. Kỹ năng này chỉ sinh <code>.bundle.yaml</code>.</li></ul><hr><h2 id="example-prompt-mau-goi" tabindex="-1">Example prompt (mẫu gọi) <a class="header-anchor" href="#example-prompt-mau-goi" aria-label="Permalink to &quot;Example prompt (mẫu gọi)&quot;">​</a></h2><p><strong>Quy tắc:</strong> một session = một command · chat mới khi đổi phase · cập nhật <code>.harness/progress.md</code> nếu có.</p><p><strong>Khi nào:</strong> Gọi khi scope khớp mô tả skill ở trên.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/common-spec</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>Surface: {admin-web} · Module: {CMP-…} · Scope: {mô tả ngắn}</span></span></code></pre></div>',20)])])}const p=n(i,[["render",t]]);export{m as __pageData,p as default};
